  "test_intents": [
    {
      "id": "INT-001",
      "objective": "验证单一或多个受限原因只返回一个实际命中的合法专用错误，不拼接消息、不固化原因优先级，并保持权限错误和信息隐藏行为。",
      "required_layers": ["backend", "contract"],
      "risk": "critical",
