    {
      "id": "INT-002",
      "objective": "验证维度、数据范围和下钻字段中的自定义维度均返回批准的中英文契约，并保持既有检测顺序及时分筛选行为。",
      "required_layers": ["backend", "contract"],
      "risk": "critical",
      "source_refs": ["REQ-002", "RULE-CUSTOM-DIMENSION", "RULE-I18N-CUSTOM-DIMENSION", "TF-004"]
