    {
      "id": "INT-004",
      "objective": "验证多关联原因依据已选关联路径和关系元数据识别，仅在原对象关系解析失败时映射专用提示，原本成功的关系继续成功。",
      "required_layers": ["backend", "contract"],
      "risk": "critical",
      "source_refs": ["REQ-004", "RULE-MULTI-RELATION", "RULE-I18N-MULTI-RELATION", "TF-009", "TF-010", "TF-011"]
    },
    {
      "id": "INT-005",
      "objective": "验证实际 what 和 what-list 对象及字段范围均按动态关联处理，不增加工单主题、业务范围或稳定标识白名单限制，并保持非关系异常原样传播。",
      "required_layers": ["backend", "contract"],
      "risk": "critical",
