      "required_layers": ["contract", "e2e"],
      "risk": "critical",
      "source_refs": ["REQ-006", "RULE-HISTORICAL-COMPATIBILITY", "RULE-PERMISSION-PRIORITY", "TF-012", "TF-013"]
    },
    {
      "id": "INT-007",
      "objective": "验证 Web 与移动端统计图、拼表四入口的路由、参数、错误码、错误 key、参数、本地化消息及正常结果一致。",
      "required_layers": ["e2e"],
      "risk": "critical",
      "source_refs": ["REQ-007", "RULE-ENTRY-CONSISTENCY", "TF-013", "FND-006"]
    }
  ],
  "parent_cases": [
    {
      "id": "TC-A08-001",
      "title": "受限原因选择、多原因单提示与权限行为",
      "intent_ids": ["INT-001"],
      "layer": "backend",
      "required_layers": ["backend", "contract"],
      "risk": "critical",
      "priority": "P0",
      "automation_candidate": true,
      "source_refs": ["REQ-001", "RULE-MULTIPLE-REASONS", "RULE-PERMISSION-PRIORITY", "TF-011", "TF-014"],
      "preconditions": [
        "可观测实际命中的原因集合、返回错误码、错误 key、消息数组、参数数组及明细查询调用次数。",
        "权限基线必须由同版本变更前响应生成版本化证据；没有该证据时仅允许人工确认。"
      ],
      "test_data": {
        "namespace": "a08_detail-drill-i18n-8card-20260817-01_TC-A08-001",
        "locales": ["zh_CN", "en"],
        "datasets": [
          {"id": "single_custom", "actually_matched_codes": ["s307011534"]},
          {"id": "single_result_set", "actually_matched_codes": ["s307011535"]},
          {"id": "single_multi_relation", "actually_matched_codes": ["s307011536"]},
          {"id": "single_dynamic_relation", "actually_matched_codes": ["s307011537"]},
          {"id": "multiple_a", "actually_matched_codes": ["s307011534", "s307011535"]},
          {"id": "multiple_b", "actually_matched_codes": ["s307011536", "s307011537"]},
          {"id": "permission_denied", "actually_matched_codes": ["s307011535"], "metric_display_names": ["收入", "Revenue"]}
        ]
      },
      "steps": [
        "逐个执行单原因和多原因数据，并从运行时判定轨迹取得 actually_matched_codes。",
        "校验返回消息数量、合法 code-message 对和拼接计数，不声明任何固定原因优先级。",
        "以无指标查看权限用户执行相同请求并保存权限响应和泄露检查证据。",
        "核对失败调用未进入明细查询，随后执行清理补偿。"
      ],
      "expected": [
        {
          "id": "EXP-001-01",
          "description": "每次受限响应的消息数恰好为一。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "detail_api.localized_messages.length",
            "matcher": "equals",
            "expected_value": 1,
            "source_ref": "RULE-MULTIPLE-REASONS"
          }
        },
        {
          "id": "EXP-001-02",
          "description": "返回的 code-message 对属于本次实际命中的合法集合。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "detail_api.returned_code_message_pair",
            "matcher": "member_of",
            "expected_value": "runtime_trace.actually_matched_code_message_pairs",
            "source_ref": "RULE-MULTIPLE-REASONS"
          }
        },
        {
          "id": "EXP-001-03",
          "description": "响应中不存在由多个原因拼接产生的额外消息。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "detail_api.concatenated_message_count",
            "matcher": "equals",
            "expected_value": 0,
            "source_ref": "RULE-MULTIPLE-REASONS"
          }
        },
        {
          "id": "EXP-001-04",
          "description": "权限响应与版本化变更前证据逐字段一致。",
          "oracle": {
            "type": "human_review",
            "observation_point": "permission_baseline_comparison_record",
            "matcher": "manual_confirmation",
            "expected_value": "评审记录包含基线标识，并逐字段比较错误码、消息、参数和响应结构",
            "source_ref": "RULE-PERMISSION-PRIORITY"
          }
        },
        {
          "id": "EXP-001-05",
          "description": "权限响应正文和参数不泄露指标展示名，且不出现四个专用错误码。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "permission_response.metric_name_or_specialized_code_occurrences",
            "matcher": "equals",
            "expected_value": 0,
            "source_ref": "RULE-PERMISSION-PRIORITY"
          }
        },
        {
          "id": "EXP-001-06",
          "description": "受限调用不进入明细查询。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "detail_query_invocation_count",
            "matcher": "equals",
            "expected_value": 0,
            "source_ref": "REQ-001"
          }
        },
        {
          "id": "EXP-001-07",
          "description": "清理后唯一命名空间内无临时资源和故障注入。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "cleanup.namespace_residual_resource_count",
            "matcher": "equals",
            "expected_value": 0,
            "source_ref": "TF-011"
          }
        }
      ],
      "cleanup": [
        "删除唯一命名空间内的图表、指标、筛选器和测试授权。",
        "恢复权限策略及故障注入开关。",
        "确认不存在残留明细查询任务。"
      ],
      "execution_policy": {
        "allowed_modes": ["automated", "manual"],
        "automation_review": "required",
        "blocking_gaps": ["缺少权限响应的版本化变更前基线和可控多原因构造器。"],
        "notes": "多原因数据只声明实际命中集合，不声明固定业务原因优先级。"
      }
    },
    {
      "id": "TC-A08-002",
      "title": "自定义维度三位置、检测顺序及时分筛选兼容",
      "intent_ids": ["INT-002"],
      "layer": "contract",
      "required_layers": ["backend", "contract"],
      "risk": "critical",
      "priority": "P0",
      "automation_candidate": true,
      "source_refs": ["REQ-002", "RULE-CUSTOM-DIMENSION", "RULE-I18N-CUSTOM-DIMENSION", "TF-004", "FND-002"],
      "preconditions": [
        "错误码平台测试环境配置 s307011534 的批准中英文模板。",
        "可观测三个既有检测分支的轨迹，并取得变更前时分筛选响应证据。"
      ],
      "test_data": {
        "namespace": "a08_detail-drill-i18n-8card-20260817-01_TC-A08-002",
        "locales": ["zh_CN", "en"],
        "matrix": [
          {"location": "dimension", "expected_branch": "existing_dimension_branch"},
          {"location": "data_range", "expected_branch": "existing_data_range_branch"},
          {"location": "drill_field", "expected_branch": "existing_drill_field_branch"}
        ],
        "control": {"location": "dimension", "field_type": "ordinary_dimension"}
      },
      "steps": [
        "逐行执行三位置矩阵并采集错误响应和分支轨迹。",
        "执行普通维度正常对照并检查成功状态、分页和结果结构。",
        "对带时分筛选的相同配置比较变更前后证据。",
        "执行清理并检查唯一命名空间。"
      ],
      "expected": [
        {
          "id": "EXP-002-01",
          "description": "三位置均返回专用错误码。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "matrix_rows.detail_api.error_code",
            "matcher": "all_equal",
            "expected_value": "s307011534",
            "source_ref": "RULE-I18N-CUSTOM-DIMENSION"
          }
        },
        {
          "id": "EXP-002-02",
          "description": "错误 key 和参数精确匹配批准契约。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "matrix_rows.detail_api.error_key_and_parameters",
            "matcher": "equals",
            "expected_value": {"key": "CUSTOM_DIMENSION_DETAIL_REASON_UNSUPPORTED", "parameters": []},
            "source_ref": "RULE-I18N-CUSTOM-DIMENSION"
          }
        },
        {
          "id": "EXP-002-03",
          "description": "中文文案精确匹配批准模板。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "zh_CN.detail_api.localized_message",
            "matcher": "equals",
            "expected_value": "维度或数据范围中使用了自定义维度字段，暂不支持查看明细",
            "source_ref": "RULE-I18N-CUSTOM-DIMENSION"
          }
        },
        {
          "id": "EXP-002-04",
          "description": "英文文案精确匹配批准模板。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "en.detail_api.localized_message",
            "matcher": "equals",
            "expected_value": "Custom dimension fields are used in the dimension or data range. Details view is not supported.",
            "source_ref": "RULE-I18N-CUSTOM-DIMENSION"
          }
        },
        {
          "id": "EXP-002-05",
          "description": "每行进入原有对应分支，分支先后轨迹与版本化变更前证据一致。",
          "oracle": {
            "type": "human_review",
            "observation_point": "branch_trace_baseline_comparison_record",
            "matcher": "manual_confirmation",
            "expected_value": "评审记录逐行包含基线标识、实际分支、进入顺序和无新增前置分支的证据",
            "source_ref": "RULE-CUSTOM-DIMENSION"
          }
        },
        {
          "id": "EXP-002-06",
          "description": "时分筛选响应与版本化变更前证据逐字段一致。",
          "oracle": {
            "type": "human_review",
            "observation_point": "time_filter_baseline_comparison_record",
            "matcher": "manual_confirmation",
            "expected_value": "评审记录比较状态、请求参数、分页、行数据和响应结构",
            "source_ref": "TF-004"
          }
        },
        {
          "id": "EXP-002-07",
          "description": "普通维度对照成功且返回分页和明细结果结构。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "ordinary_dimension_control.success_contract",
            "matcher": "equals",
            "expected_value": {"success": true, "pagination_present": true, "result_rows_present": true},
            "source_ref": "RULE-HISTORICAL-COMPATIBILITY"
          }
        },
        {
          "id": "EXP-002-08",
          "description": "清理后命名空间无残留。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "cleanup.namespace_residual_resource_count",
            "matcher": "equals",
            "expected_value": 0,
            "source_ref": "TF-004"
          }
        }
      ],
      "cleanup": [
        "删除三位置测试配置及普通维度对照。",
        "恢复语言和时分筛选基线。",
        "清除接口缓存并检查命名空间残留。"
      ],
      "execution_policy": {
        "allowed_modes": ["automated", "manual"],
        "automation_review": "required",
        "blocking_gaps": ["缺少检测分支轨迹和时分筛选的版本化变更前基线。"],
        "notes": "没有冻结基线的兼容性比较必须采用人工确认。"
      }
    },
    {
      "id": "TC-A08-003",
      "title": "结果集筛选名称解析优先级、全部名称参数与本地化",
      "intent_ids": ["INT-003"],
      "layer": "contract",
      "required_layers": ["backend", "contract"],
      "risk": "critical",
      "priority": "P0",
      "automation_candidate": true,
      "source_refs": ["REQ-003", "RULE-SINGLE-METRIC", "RULE-I18N-RESULT-SET", "TF-005", "TF-006", "TF-007", "TF-008", "FND-003"],
      "preconditions": [
        "可构造三个名称来源互相冲突的结果集筛选数据。",
        "可观测 BIBizException 的 List<String> 参数和最终接口文案。"
      ],
      "test_data": {
        "namespace": "a08_detail-drill-i18n-8card-20260817-01_TC-A08-003",
        "locales": ["zh_CN", "en"],
        "matrix": [
          {
            "row_id": "name_from_filter",
            "filter_field_name": "收入 \"净额\"",
            "metadata_name": "元数据候选",
            "dynamic_locale_name": "动态候选",
            "expected_parameter": "收入 \"净额\""
          },
          {
            "row_id": "name_from_metadata",
            "filter_field_name": null,
            "metadata_name": "成本 \"计划\"",
            "dynamic_locale_name": "动态候选",
            "expected_parameter": "成本 \"计划\""
          },
          {
            "row_id": "name_from_dynamic_locale",
            "filter_field_name": null,
            "metadata_name": null,
            "dynamic_locale_name": "Revenue \"Net\"",
            "expected_parameter": "Revenue \"Net\""
          }
        ],
        "multiple_metrics": ["收入", "成本"],
        "metric_types": ["ordinary", "aggregate", "calculated", "period_comparison"],
        "skipped_scenarios": ["三个名称来源均为空的场景不生成"]
      },
      "steps": [
        "逐行执行名称来源冲突矩阵并记录单次异常参数。",
        "分别执行四种指标类型并检查专用错误契约。",
        "执行两个受限指标并检查全部名称参数。",
        "验证中英文最终消息及无结果集筛选正常对照。"
      ],
      "expected": [
        {
          "id": "EXP-003-01",
          "description": "四种指标类型均返回结果集筛选专用错误。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "metric_type_rows.detail_api.error_contract",
            "matcher": "all_equal",
            "expected_value": {"code": "s307011535", "key": "RESULT_SET_FILTER_DETAIL_UNSUPPORTED"},
            "source_ref": "RULE-I18N-RESULT-SET"
          }
        },
        {
          "id": "EXP-003-02A",
          "description": "来源冲突时优先使用 Filter.fieldName。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "name_from_filter.backend_exception.metric_name_parameters",
            "matcher": "equals",
            "expected_value": ["收入 \"净额\""],
            "source_ref": "RULE-SINGLE-METRIC"
          }
        },
        {
          "id": "EXP-003-02B",
          "description": "Filter.fieldName 缺失时使用 fieldId 元数据名称。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "name_from_metadata.backend_exception.metric_name_parameters",
            "matcher": "equals",
            "expected_value": ["成本 \"计划\""],
            "source_ref": "RULE-SINGLE-METRIC"
          }
        },
        {
          "id": "EXP-003-02C",
          "description": "前两级缺失时使用当前语言动态名称。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "name_from_dynamic_locale.backend_exception.metric_name_parameters",
            "matcher": "equals",
            "expected_value": ["Revenue \"Net\""],
            "source_ref": "RULE-SINGLE-METRIC"
          }
        },
        {
          "id": "EXP-003-03",
          "description": "多个受限指标的全部非空名称进入参数契约。",
          "oracle": {
            "type": "deterministic",
            "observation_point": "multiple_metrics.backend_exception.metric_name_parameters",
            "matcher": "equals",
            "expected_value": ["收入", "成本"],
            "source_ref": "RULE-SINGLE-METRIC"
          }
        },
        {
          "id": "EXP-003-04",
